CREATE DATABASE INAI_Coffee CHARACTER SET utf8mb4;
USE INAI_Coffee;
CREATE TABLE Kategoriya (id INT AUTO_INCREMENT PRIMARY KEY, nazvanie VARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE Klient (id INT AUTO_INCREMENT PRIMARY KEY, fio VARCHAR(100) NOT NULL, telefon VARCHAR(20) UNIQUE, bonus INT DEFAULT 0 CHECK(bonus>=0), email VARCHAR(100) CHECK(email LIKE '%@%'));
CREATE TABLE Sotrudnik (id INT AUTO_INCREMENT PRIMARY KEY, fio VARCHAR(100) NOT NULL, id_boss INT, FOREIGN KEY (id_boss) REFERENCES Sotrudnik(id));
CREATE TABLE Tovar (id INT AUTO_INCREMENT PRIMARY KEY, nazvanie VARCHAR(100) NOT NULL UNIQUE, cena DECIMAL(10,2) NOT NULL CHECK(cena>0), id_kategoriya INT, FOREIGN KEY (id_kategoriya) REFERENCES Kategoriya(id));
CREATE TABLE Zakaz (id INT AUTO_INCREMENT PRIMARY KEY, id_klient INT NOT NULL, id_sotrudnik INT, data DATE DEFAULT (CURRENT_DATE) NOT NULL, summa DECIMAL(10,2) NOT NULL CHECK(summa>=0), FOREIGN KEY (id_klient) REFERENCES Klient(id), FOREIGN KEY (id_sotrudnik) REFERENCES Sotrudnik(id));
CREATE TABLE Sostav_zakaza (id INT AUTO_INCREMENT PRIMARY KEY,id_zakaz INT NOT NULL,id_tovar INT NOT NULL,qty INT NOT NULL CHECK(qty>0),price DECIMAL(10,2) NOT NULL CHECK(price>0), FOREIGN KEY (id_zakaz) REFERENCES Zakaz(id), FOREIGN KEY (id_tovar) REFERENCES Tovar(id));
